mapper.select:
SELECT id
FROM knowledge_document
WHERE tenant_id = #{tenantId}
  AND status = 'PUBLISHED'

      AND document_key = #{documentKey}


      AND version = #{version}

SELECT ks.id, ks.vector_id, ks.knowledge_document_id, ks.tenant_id, ks.document_key, ks.version, ks.segment_index, ks.segment_text, ks.source_uri, MATCH(ks.segment_text) AGAINST( #{query} IN NATURAL LANGUAGE MODE ) AS keyword_score FROM knowledge_segment ks INNER JOIN knowledge_document kd ON kd.id = ks.knowledge_document_id WHERE ks.tenant_id = #{tenantId} AND kd.status = 'PUBLISHED' AND MATCH(ks.segment_text) AGAINST( #{query} IN NATURAL LANGUAGE MODE )
AND ks.document_key = #{documentKey}
AND ks.version = #{version}
ORDER BY keyword_score DESC LIMIT #{limit}
